<section class="card form-card account-card"><div class="card-head"><div><h3><?= e($subscription['first_name'].' '.$subscription['last_name']) ?></h3><p>Abonnement n° <?= (int)$subscription['id'] ?> · <?= e($subscription['plan']) ?></p></div><a class="text-link" href="index.php?page=subscriptions">← Abonnements</a></div>
<p>Ancienne période : <strong><?= e(date('d/m/Y',strtotime($subscription['start_date']))) ?> – <?= e(date('d/m/Y',strtotime($subscription['end_date']))) ?></strong> · Prix fixé : <strong><?= $subscription['agreed_price']===null ? 'À vérifier' : e(dt($subscription['agreed_price'])) ?></strong></p>
