<form method="post" action="index.php?page=subscription_renew&amp;id=<?= (int)$subscription['id'] ?>" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="subscription_version" value="<?= e($version) ?>"><input type="hidden" name="start" value="<?= e($start) ?>"><label>Formule du renouvellement *<select name="plan" required><option value="">Sélectionner</option><?php foreach ($plans as $plan): ?><option value="<?= (int)$plan['id'] ?>|<?= e(PlanService::version($plan)) ?>" <?= (int)$plan['id']===$chosenPlan ? 'selected' : '' ?>><?= e($plan['name'].' · '.(int)$plan['duration_days'].' jours · '.dt($plan['price'])) ?></option><?php endforeach; ?></select></label><p class="form-hint">La durée comprend le jour de début. Les périodes actives ne peuvent pas se chevaucher ; une formule désactivée ne peut pas être choisie.</p><div class="form-actions"><button class="primary" type="submit" data-confirm="Créer ce renouvellement sans enregistrer de paiement ?" onclick="return confirm(this.dataset.confirm)">Confirmer le renouvellement</button></div></form><?php endif; ?></section>
